#include "cinderwatch/cli/cli.h"
#include "cinderwatch/policy/policy.h"
#include <iostream>
namespace cinderwatch::cli{using namespace core;static bool js(const std::vector<std::string>&a){return std::find(a.begin(),a.end(),"--json")!=a.end();}static bool need(const std::vector<std::string>&a,size_t n){if(a.size()<n){std::cerr<<"missing arguments\n";return true;}return false;}int run(const std::vector<std::string>&args){if(args.size()<2){std::cout<<"cinderwatch commands: inspect-pcap summarize-pcap scan-ioc validate-firewall inspect-ids normalize-ids validate-policy audit-bundle\n";return 2;}auto c=args[1];bool j=js(args);if(c=="inspect-pcap"||c=="summarize-pcap"){if(need(args,3))return 2;auto a=packet::analyze_file(args[2]);std::cout<<(j?packet::json(a):packet::text(a));return a.report.fail()?1:0;}if(c=="scan-ioc"){if(need(args,4))return 2;auto s=ioc::load_file(args[2]);auto t=read_text(args[3]);if(!t){std::cerr<<t.st.msg<<"\n";return 2;}auto m=ioc::match_text(s,args[3],t.value());std::cout<<(j?ioc::json(m):ioc::text(m));return m.empty()?0:1;}if(c=="validate-firewall"){if(need(args,3))return 2;auto t=read_text(args[2]);if(!t)return 2;auto s=rules::parse_firewall(t.value());auto r=rules::validate_firewall(s);std::cout<<(j?rules::firewall_json(s,r):rules::firewall_text(s,r));return r.fail()?1:0;}if(c=="inspect-ids"){if(need(args,3))return 2;auto t=read_text(args[2]);if(!t)return 2;auto s=rules::parse_ids_rules(t.value());auto r=rules::validate_ids(s);std::cout<<(j?rules::ids_json(s,r):rules::ids_text(s,r));return r.fail()?1:0;}if(c=="normalize-ids"){if(need(args,3))return 2;auto t=read_text(args[2]);if(!t)return 2;auto s=rules::parse_ids_rules(t.value());std::cout<<rules::normalize_ids(s);return s.diagnostics.empty()?0:1;}if(c=="validate-policy"){if(need(args,3))return 2;auto p=policy::parse_file(args[2]);auto r=policy::validate(p);std::cout<<(j?policy::json(p,r):policy::text(p,r));return r.fail()?1:0;}if(c=="audit-bundle"){if(need(args,3))return 2;auto r=policy::audit_bundle(args[2]);std::cout<<(j?report_json(r):report_text(r));return r.fail()?1:0;}std::cerr<<"unknown command\n";return 2;}}
